      ],
      "assessment": {
        "nobel_worthiness": "Numerical relativity made it possible to calculate the strong-field merger of two black holes and predict the gravitational-wave signals later observed. It is a major conceptual and practical advance in gravitation.",
        "attribution": "Pretorius's stable merger simulation and the independent breakthroughs by the Baker and Campanelli groups mark clear, complementary contributions.",
        "maturity": "The methods have been extensively developed and are central to interpreting gravitational-wave observations.",
        "uncertainties": [
          "The wider community's contributions to the numerical-relativity toolkit make the boundaries of individual credit worth careful review."
        ]
      }
    },
