      "proposed_laureates": [
        "Michele Parrinello",
        "Roberto Car"
      ],
      "assessment": {
        "nobel_worthiness": "The Car–Parrinello method joined quantum electronic-structure calculations to molecular dynamics in a way that opened atomistic simulation to many problems in condensed matter and chemistry.",
        "attribution": "The method is explicitly associated with the closely paired work of Car and Parrinello.",
        "maturity": "Its influence is long established, with decades of use and extensions across computational physics.",
        "uncertainties": [
          "The prize case depends on judging a broadly useful computational method as a fundamental physics contribution rather than primarily as a tool."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B022",
      "proposed_laureates": [
        "Alexander A. Belavin",
        "Alexander B. Zamolodchikov",
        "Alexander M. Polyakov"
      ],
      "assessment": {
        "nobel_worthiness": "The exact two-dimensional conformal-field-theory framework transformed the understanding of critical phenomena and connected statistical physics with quantum field theory.",
        "attribution": "Belavin, Polyakov, and Zamolodchikov are the identifiable authors of the foundational construction.",
        "maturity": "The results have been tested against solvable models and have remained foundational across several areas of theory.",
        "uncertainties": [
          "The reach of this theoretical achievement across subfields may make its significance harder to convey to a broad physics audience."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B030",
      "proposed_laureates": [
        "Hidetoshi Katori",
        "Jun Ye"
      ],
      "assessment": {
        "nobel_worthiness": "Optical lattice clocks combine exceptional precision with a clear physical advance in controlling atomic transitions, enabling new tests of fundamental physics as well as better timekeeping.",
        "attribution": "Katori and Ye led distinct, influential approaches that established the field.",
        "maturity": "The clocks have been repeatedly improved and compared, and their precision has made new measurements possible.",
        "uncertainties": [
          "The lasting fundamental impact of the most recent clock applications is still unfolding."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B014",
      "proposed_laureates": [
        "Carlton M. Caves",
        "H. Jeff Kimble",
        "Roman Schnabel"
      ],
      "assessment": {
        "nobel_worthiness": "Squeezed light applies quantum mechanics to measurement noise and has enabled sensitivity beyond the standard quantum limit in important experiments, including gravitational-wave detection.",
        "attribution": "Caves supplied influential theoretical foundations, Kimble advanced experimental quantum optics, and Schnabel helped bring squeezing into precision interferometry.",
        "maturity": "The effect is well confirmed and now used in demanding measurements.",
        "uncertainties": [
          "The field's contributions are broad, and these three represent distinct stages rather than an exhaustive account of the experimental development."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B049",
      "proposed_laureates": [
        "Michael Berry",
        "Yakir Aharonov"
      ],
      "assessment": {
        "nobel_worthiness": "The Aharonov–Bohm and Berry phases showed that quantum phase has observable consequences and deepened understanding of how potentials and geometry enter quantum mechanics.",
        "attribution": "Aharonov is central to the former effect and Berry to the latter; both contributions are clearly associated with the named physicists.",
        "maturity": "The phases have been confirmed and used across many areas of physics.",
        "uncertainties": [
          "The ballot combines two related but distinct discoveries, each with additional experimental and theoretical contributors."
        ]
      }
    },
